// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.leak;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LeakDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        // LEAKY: every entry stays forever in a static list (a GC root).
        for (int i = 0; i < 1000; i++) {
            AuditTrail.record("TXN-" + i + " " + rajesh.getBalance());
        }
        log.warning(() -> "LEAKY AuditTrail size (never shrinks): " + AuditTrail.size());

        // FIXED: bounded trail evicts oldest, so memory stays flat.
        BoundedAuditTrail bounded = new BoundedAuditTrail(100); // cap at 100
        for (int i = 0; i < 1000; i++) {
            bounded.record("TXN-" + i + " " + priya.getBalance());
        }
        log.info(() -> "BOUNDED AuditTrail size (capped): " + bounded.size());

        // Listener leak prevention: register then DEREGISTER when done.
        Runnable listener = () -> log.fine(() -> "balance changed");
        bounded.addListener(listener);
        bounded.removeListener(listener); // critical: avoid retaining dead listeners
        log.info(() -> "Listener count after cleanup: " + bounded.listenerCount());
    }
}

