class Account {
    private final String accountId;
    private final String holderName;
    private final BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in AuditTrail.java (LEAKY) ───
class AuditTrail {
    // Static unbounded list = permanent GC root that never releases entries.
    private static final java.util.List<String> ENTRIES = new java.util.ArrayList<>();
    static void record(String entry) { ENTRIES.add(entry); } // grows forever
    static int size() { return ENTRIES.size(); }
}

// ─── Would be in BoundedAuditTrail.java (FIXED) ───
class BoundedAuditTrail {
    private final int capacity;
    private final java.util.Deque<String> entries = new java.util.ArrayDeque<>();
    private final java.util.List<Runnable> listeners = new java.util.ArrayList<>();

    BoundedAuditTrail(int capacity) { this.capacity = capacity; }

    void record(String entry) {
        if (entries.size() >= capacity) entries.pollFirst(); // evict oldest
        entries.addLast(entry);
    }
    int size() { return entries.size(); }

    void addListener(Runnable l) { listeners.add(l); }
    void removeListener(Runnable l) { listeners.remove(l); } // prevent listener leak
    int listenerCount() { return listeners.size(); }
}
